import numpy as np
p=np.load('source_pixels.npz')['rgb'].astype(int)
R,G,B=p[:,:,:,0],p[:,:,:,1],p[:,:,:,2]
masks={
'blue':(B>R+20)&(G>R+15)&(B>140),
'pink':(R>G+25)&(R>B+10)&(R>140),
'yellow':(R>G+10)&(G>B+20)&(R>150),
'white':(R>215)&(G>215)&(B>215)&(np.abs(R-G)<15),
'dark':(R<100)&(G<100)&(B<100),
}
for name,m in masks.items():
 print('\\n',name)
 for t in range(0,96,8):
  ys,xs=np.where(m[t])
  if len(xs): print(f'{t:2d}: n={len(xs):5d} c=({xs.mean():.1f},{ys.mean():.1f}) bbox=({xs.min()},{ys.min()},{xs.max()},{ys.max()})')
  else: print(t,0)
PY"

